INSERT INTO `wp_snippets` VALUES (1,'Make upload filenames lowercase','Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'sanitize_file_name\', \'mb_strtolower\' );','sample, media','global',0,10,0,'2026-06-09 10:26:49',1,NULL);
INSERT INTO `wp_snippets` VALUES (2,'Disable admin bar','Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_action( \'wp\', function () {\n	if ( ! current_user_can( \'manage_options\' ) ) {\n		show_admin_bar( false );\n	}\n} );','sample, admin-bar','front-end',0,10,0,'2026-06-09 10:26:49',1,NULL);
INSERT INTO `wp_snippets` VALUES (3,'Allow smilies','Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','add_filter( \'widget_text\', \'convert_smilies\' );\nadd_filter( \'the_title\', \'convert_smilies\' );\nadd_filter( \'wp_title\', \'convert_smilies\' );\nadd_filter( \'get_bloginfo\', \'convert_smilies\' );','sample','global',0,10,0,'2026-06-09 10:26:49',1,NULL);
INSERT INTO `wp_snippets` VALUES (4,'Current year','Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.','<?php echo date( \'Y\' ); ?>','sample, dates','content',0,10,0,'2026-06-09 10:26:49',1,NULL);
INSERT INTO `wp_snippets` VALUES (5,'Free shipping notice','','add_action( \'wp_footer\', \'test_snippet\' );\nfunction test_snippet() {\n    echo \'<div style=\"background:red;color:white;padding:20px;position:fixed;bottom:0;left:0;right:0;\">CODE SNIPPETS WORKS</div>\';\n}','','global',0,10,0,'2026-06-09 10:28:51',1,NULL);
INSERT INTO `wp_snippets` VALUES (6,'Cart counter in menu','','add_filter( \'wp_nav_menu_items\', \'add_cart_icon_to_menu\', 10, 2 );\nfunction add_cart_icon_to_menu( $items, $args ) {\n    $count = WC()->cart->get_cart_contents_count();\n    $items .= \'<li class=\"menu-item\"><a href=\"\' . wc_get_cart_url() . \'\">Cart (\' . $count . \')</a></li>\';\n    return $items;\n}','','global',0,10,0,'2026-06-09 10:49:50',1,NULL);
INSERT INTO `wp_snippets` VALUES (7,'Hide flat rate when free shipping available','','add_filter( \'woocommerce_package_rates\', \'hide_flat_rate_when_free_shipping\', 10, 2 );\nfunction hide_flat_rate_when_free_shipping( $rates, $package ) {\n    $free = array();\n    foreach ( $rates as $rate_id => $rate ) {\n        if ( \'free_shipping\' === $rate->method_id ) {\n            $free[ $rate_id ] = $rate;\n        }\n    }\n    return ! empty( $free ) ? $free : $rates;\n}','','global',0,10,1,'2026-06-09 10:59:24',1,NULL);
